{
  "quantity": {
    "description": "Change in own-team expected single-game scoring margin from adopting the strategy",
    "units": "points",
    "support": "unbounded real; positive favors own team"
  },
  "strategies": [
    {
      "bucket": "analytics",
      "type": "game_management",
      "title": "Model-Calibrated Fourth-Down Aggression",
      "recommendation": "Use a current, team-adjusted win-probability model as the default on fourth down, accepting its go recommendations unless the staff has specific information absent from the model. This means going more often near midfield and in manageable short-yardage situations rather than defaulting to punts or field goals.",
      "rationale": "Public expected-points and win-probability models repeatedly find that teams surrender value through excessive conservatism. Retaining possession and potential touchdowns should outweigh the field-position cost often enough to increase games won.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.37,
          "interval_95_low": -0.47,
          "interval_95_high": 1.21,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The evidence supports a positive center, but model misspecification, quarterback sneaks, special-teams quality, and high-leverage deployment create meaningful risk of a surprisingly large effect in either direction."
        },
        "parameters": {
          "nu": 7,
          "mu": 0.37,
          "sigma": 0.3559,
          "conversion_note": "Using t_{0.975,7} approximately 2.36: mu = most_plausible = 0.37, and sigma = (1.21 - (-0.47)) / (2 × 2.36) = 1.68 / 4.72 = 0.3559. This is a subjective prior calibration, not an empirical standard error."
        },
        "consistency_check": "The mode 0.37 lies inside [-0.47, 1.21]. A Student-t distribution has support over all real values, so both beneficial and harmful effects are possible; the interval uses the stated approximate critical value."
      }
    },
    {
      "bucket": "analytics",
      "type": "offensive",
      "title": "Neutral-Down Passing Bias",
      "recommendation": "Increase first-down passing in neutral game states, especially when the defense loads the box, while preserving run checks against favorable fronts. Avoid waiting for obvious passing downs to feature the quarterback.",
      "rationale": "Public expected-points research generally finds passing more productive than rushing and finds early-down passing less predictable than third-down passing. Creating more first downs and avoiding third-and-long should increase scoring margin.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.29,
          "interval_95_low": -0.39,
          "interval_95_high": 0.97,
          "shape": "symmetric",
          "tails": "light"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "The expected benefit is modest and reasonably bounded because personnel quality and selection effects limit how directly league-wide efficiency findings transfer to one offense."
        },
        "parameters": {
          "mu": 0.29,
          "sigma": 0.3469,
          "conversion_note": "mu = most_plausible = 0.29. Using the normal conversion, sigma = (0.97 - (-0.39)) / 3.92 = 1.36 / 3.92 = 0.3469, giving 0.29 ± 1.96 × 0.3469 approximately [-0.39, 0.97]. The width is a subjective prior judgment."
        },
        "consistency_check": "The mode and mean 0.29 lie inside [-0.39, 0.97]. The normal distribution has unbounded real support and therefore permits a negative effect."
      }
    },
    {
      "bucket": "analytics",
      "type": "defensive",
      "title": "Coverage-First Neutral Downs",
      "recommendation": "Outside short yardage, default more often to nickel or dime personnel, light boxes, and calls that protect against passes, accepting some efficient runs before adding a defender. Adjust only when the opponent demonstrates that its rushing advantage is large enough to justify weakening coverage.",
      "rationale": "Public expected-points work shows that passes and explosive completions generally impose more damage than ordinary runs, while box-count research suggests defenses frequently spend resources suppressing the less valuable outcome. The evidence is more observational and less decisive than offensive analytics, so the expected gain is small.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.14,
          "interval_95_low": -0.62,
          "interval_95_high": 0.9,
          "shape": "symmetric",
          "tails": "moderate"
        },
        "distribution_family": {
          "name": "normal",
          "justification": "A normal prior reflects a modest central benefit with substantial uncertainty. The broad interval acknowledges confounding in public defensive studies and the possibility that a particular roster cannot stop the run from light boxes."
        },
        "parameters": {
          "mu": 0.14,
          "sigma": 0.3878,
          "conversion_note": "mu = most_plausible = 0.14. Sigma = (0.90 - (-0.62)) / 3.92 = 1.52 / 3.92 = 0.3878, so the implied central interval is 0.14 ± 1.96 × 0.3878 approximately [-0.62, 0.90]. This is a deliberately weak subjective prior."
        },
        "consistency_check": "The mode and mean 0.14 lie inside [-0.62, 0.90]. The normal family's support is all real numbers, including harmful effects."
      }
    },
    {
      "bucket": "intuition",
      "type": "game_management",
      "title": "Explosive-Prevention Timeout",
      "recommendation": "Authorize the defensive signal-caller to spend a timeout when late motion or communication failure leaves an unmistakable coverage bust or severe leverage mismatch before the snap, including in the first half. The trigger must be narrow enough that ordinary uncertainty does not consume timeouts.",
      "rationale": "Preventing one uncontested explosive play can outweigh the future clock value of a timeout, but unnecessary use can lose a late possession. This is intuition because public models value remaining timeouts but generally cannot observe or causally evaluate the pre-snap defensive failures that would trigger this policy.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.03,
          "interval_95_low": -0.49,
          "interval_95_high": 0.55,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The average effect is probably near zero because the trigger is rare, but an unusually good or bad implementation could have a much larger impact, warranting heavy tails."
        },
        "parameters": {
          "nu": 4,
          "mu": 0.03,
          "sigma": 0.1871,
          "conversion_note": "Using t_{0.975,4} approximately 2.78: mu = 0.03, and sigma = (0.55 - (-0.49)) / (2 × 2.78) = 1.04 / 5.56 = 0.1871. Sigma is the Student-t scale, not its standard deviation; this is a subjective calibration."
        },
        "consistency_check": "The mode 0.03 lies inside [-0.49, 0.55]. The Student-t distribution has unbounded signed support; the interval is approximate because the critical value is rounded."
      }
    },
    {
      "bucket": "intuition",
      "type": "offensive",
      "title": "Paired-Call Quarterback Autonomy",
      "recommendation": "Install a small menu of two-play calls from identical personnel and formations, allowing the quarterback to choose between them from one clearly defined post-snap or late-pre-snap key. Keep the menu small enough to preserve execution speed and disguise.",
      "rationale": "The offense can attack the defense's actual structure without substituting or revealing intent, potentially turning bad called looks into favorable ones. This qualifies as intuition because public play-by-play data rarely records checks or paired-call rules, and available evidence on quarterback autonomy is mixed and strongly confounded by quarterback quality.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.08,
          "interval_95_low": -0.69,
          "interval_95_high": 0.85,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The likely benefit is small, but quarterback processing, coaching design, and added mental burden could produce materially positive or negative outliers."
        },
        "parameters": {
          "nu": 7,
          "mu": 0.08,
          "sigma": 0.3263,
          "conversion_note": "Using t_{0.975,7} approximately 2.36: mu = 0.08, and sigma = (0.85 - (-0.69)) / (2 × 2.36) = 1.54 / 4.72 = 0.3263. This scale was selected to express subjective uncertainty rather than estimated from a causal dataset."
        },
        "consistency_check": "The mode 0.08 lies inside [-0.69, 0.85]. Student-t support spans the entire real line, allowing the strategy to backfire; the interval is approximate because 2.36 is rounded."
      }
    },
    {
      "bucket": "intuition",
      "type": "defensive",
      "title": "Post-Huddle Matchup Swaps",
      "recommendation": "Cross-train the nickel, safeties, and selected corners to exchange man-match responsibilities after the offense declares its formation while preserving the same apparent shell. Use the swaps selectively rather than adding them to every call.",
      "rationale": "Changing which defender owns a route can invalidate the quarterback's preferred matchup and create hesitation, sacks, or turnover opportunities without requiring a blitz. This is intuition because public data does not reliably identify these responsibility exchanges, and there is no settled causal evidence that their deception value exceeds the added risk of coverage busts.",
      "prior": {
        "belief_summaries": {
          "most_plausible_value": 0.05,
          "interval_95_low": -0.91,
          "interval_95_high": 1.01,
          "shape": "symmetric",
          "tails": "heavy"
        },
        "distribution_family": {
          "name": "student_t",
          "justification": "The center is deliberately close to zero because this is a weak, implementation-dependent hypothesis. Heavy tails represent the possibility of either a genuinely disruptive system or costly communication failures."
        },
        "parameters": {
          "nu": 4,
          "mu": 0.05,
          "sigma": 0.3453,
          "conversion_note": "Using t_{0.975,4} approximately 2.78: mu = 0.05, and sigma = (1.01 - (-0.91)) / (2 × 2.78) = 1.92 / 5.56 = 0.3453. Sigma is the scale parameter, and the chosen width is an honest subjective prior rather than a precise measurement."
        },
        "consistency_check": "The mode 0.05 lies inside [-0.91, 1.01]. The Student-t family has unbounded real support, so it represents both improvement and backfire risk; the reported interval is approximate."
      }
    }
  ]
}
